INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is an ''overflow'' (or ''soft-flow'') dyeing machine, and what fabric handling advantage does it offer for delicate fabrics?', '["It circulates fabric (in rope form) using a gentle flow of liquor rather than mechanical reels/rollers alone, reducing mechanical stress on delicate fabrics","It only works by completely submerging fabric with zero liquor movement at all","It applies dye exclusively via a printing screen mechanism, with no liquor bath involved","It is used only for extremely heavy, rigid technical fabrics, never delicate ones"]'::jsonb, 'It circulates fabric (in rope form) using a gentle flow of liquor rather than mechanical reels/rollers alone, reducing mechanical stress on delicate fabrics', 'Overflow/soft-flow dyeing machines use a moving liquor stream (rather than harsher mechanical winch reels) to gently carry rope-form fabric through the dyeing vessel, reducing mechanical stress/abrasion — well suited to delicate or easily-creased fabrics that need gentler handling than older winch-style machines provide.', 2, '{"overflow-dyeing-machine"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''perspiration fastness'' testing meant to simulate and evaluate?', '["How well a dyed fabric''s color resists change or bleeding when exposed to conditions simulating human sweat (acidic and alkaline solutions)","How a fabric responds to prolonged direct sunlight exposure","How a fabric performs under repeated machine washing cycles","How a fabric responds to dry heat exposure during ironing"]'::jsonb, 'How well a dyed fabric''s color resists change or bleeding when exposed to conditions simulating human sweat (acidic and alkaline solutions)', 'Perspiration fastness tests expose a dyed sample to standardized acidic and alkaline solutions (simulating human sweat''s varying pH) under controlled conditions, then assess color change and any staining transferred to adjacent fabric — relevant for garments in direct, prolonged skin contact.', 1, '{"perspiration-fastness"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why might a dye that performs well in standard wash-fastness testing still show poor performance in perspiration-fastness testing?', '["Sweat''s chemical composition (varying pH, salts) creates different conditions than a standard detergent wash, which can affect certain dyes'' stability differently than plain washing does","Wash fastness and perspiration fastness always test for identical chemical exposure conditions with no meaningful difference","Perspiration fastness testing is always easier to pass than wash fastness testing for every dye class","A dye''s performance in one fastness test always perfectly predicts its performance in every other fastness test"]'::jsonb, 'Sweat''s chemical composition (varying pH, salts) creates different conditions than a standard detergent wash, which can affect certain dyes'' stability differently than plain washing does', 'Since perspiration involves a different chemical environment (varying acidic/alkaline pH, salts, urea) than a standard detergent wash cycle, a dye''s stability can respond differently to each — meaning good wash fastness doesn''t automatically guarantee good perspiration fastness, requiring both properties to be tested separately for garments in direct skin contact.', 2, '{"perspiration-vs-wash-fastness"}'::text[]);
COMMIT;
